-- Initial PostgreSQL schema for Impulse Connect.
CREATE SCHEMA IF NOT EXISTS "public";
CREATE TYPE "Role" AS ENUM ('ADMIN','MANAGER','AGENT','VIEWER');
CREATE TYPE "LeadStatus" AS ENUM ('NOVO','PESQUISADO','PRONTO_PARA_CONTATO','CONTATADO','RESPONDEU','INTERESSADO','REUNIAO','PROPOSTA','CLIENTE','SEM_INTERESSE','NAO_CONTATAR');
CREATE TYPE "ConsentStatus" AS ENUM ('UNKNOWN','OPTED_IN','OPTED_OUT');
CREATE TYPE "MessageDirection" AS ENUM ('INBOUND','OUTBOUND');
CREATE TYPE "MessageType" AS ENUM ('TEXT','IMAGE','DOCUMENT','INTERACTIVE','TEMPLATE');
CREATE TYPE "MessageStatus" AS ENUM ('QUEUED','SENT','DELIVERED','READ','FAILED');
CREATE TYPE "CampaignStatus" AS ENUM ('DRAFT','AWAITING_APPROVAL','SCHEDULED','RUNNING','PAUSED','COMPLETED','CANCELLED','FAILED');
CREATE TYPE "TemplateStatus" AS ENUM ('APPROVED','PENDING','REJECTED','PAUSED','DISABLED');
CREATE TABLE "User" ("id" TEXT NOT NULL,"email" TEXT NOT NULL,"name" TEXT NOT NULL,"role" "Role" NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Lead" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"company" TEXT,"phone" TEXT,"normalizedPhone" TEXT,"email" TEXT,"instagram" TEXT,"googleMaps" TEXT,"site" TEXT,"city" TEXT,"state" TEXT,"niche" TEXT,"source" TEXT,"observations" TEXT,"status" "LeadStatus" NOT NULL DEFAULT 'NOVO',"assignedUserId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Lead_pkey" PRIMARY KEY ("id"));
CREATE TABLE "LeadNote" ("id" TEXT NOT NULL,"leadId" TEXT NOT NULL,"userId" TEXT NOT NULL,"body" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "LeadNote_pkey" PRIMARY KEY ("id"));
CREATE TABLE "LeadHistory" ("id" TEXT NOT NULL,"leadId" TEXT NOT NULL,"type" TEXT NOT NULL,"details" JSONB,"userId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "LeadHistory_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Conversation" ("id" TEXT NOT NULL,"leadId" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'OPEN',"lastMessageAt" TIMESTAMP(3),"windowOpenUntil" TIMESTAMP(3),CONSTRAINT "Conversation_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Message" ("id" TEXT NOT NULL,"conversationId" TEXT NOT NULL,"providerMessageId" TEXT,"direction" "MessageDirection" NOT NULL,"type" "MessageType" NOT NULL,"content" TEXT NOT NULL,"templateName" TEXT,"status" "MessageStatus" NOT NULL DEFAULT 'QUEUED',"idempotencyKey" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"sentAt" TIMESTAMP(3),"deliveredAt" TIMESTAMP(3),"readAt" TIMESTAMP(3),"failedAt" TIMESTAMP(3),"errorCode" TEXT,"errorMessage" TEXT,CONSTRAINT "Message_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Campaign" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"templateName" TEXT NOT NULL,"segment" JSONB NOT NULL,"createdBy" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"scheduledAt" TIMESTAMP(3),"status" "CampaignStatus" NOT NULL DEFAULT 'DRAFT',CONSTRAINT "Campaign_pkey" PRIMARY KEY ("id"));
CREATE TABLE "CampaignRecipient" ("id" TEXT NOT NULL,"campaignId" TEXT NOT NULL,"leadId" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'PENDING',CONSTRAINT "CampaignRecipient_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Template" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"language" TEXT NOT NULL,"category" TEXT NOT NULL,"status" "TemplateStatus" NOT NULL,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Template_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Consent" ("id" TEXT NOT NULL,"leadId" TEXT NOT NULL,"status" "ConsentStatus" NOT NULL DEFAULT 'UNKNOWN',"source" TEXT,"date" TIMESTAMP(3),"text" TEXT,"proof" TEXT,"category" TEXT,"formVersion" TEXT,"ip" TEXT,CONSTRAINT "Consent_pkey" PRIMARY KEY ("id"));
CREATE TABLE "OptOut" ("id" TEXT NOT NULL,"leadId" TEXT NOT NULL,"blockedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"reason" TEXT NOT NULL,CONSTRAINT "OptOut_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Task" ("id" TEXT NOT NULL,"leadId" TEXT NOT NULL,"title" TEXT NOT NULL,"dueDate" TIMESTAMP(3),"assignedTo" TEXT,"completed" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Task_pkey" PRIMARY KEY ("id"));
CREATE TABLE "WebhookEvent" ("id" TEXT NOT NULL,"eventId" TEXT NOT NULL,"timestamp" TIMESTAMP(3) NOT NULL,"payloadHash" TEXT NOT NULL,"status" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "WebhookEvent_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AuditLog" ("id" TEXT NOT NULL,"userId" TEXT,"action" TEXT NOT NULL,"entity" TEXT NOT NULL,"entityId" TEXT,"timestamp" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"ip" TEXT,"metadata" JSONB,CONSTRAINT "AuditLog_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SystemSetting" ("key" TEXT NOT NULL,"value" JSONB NOT NULL,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "SystemSetting_pkey" PRIMARY KEY ("key"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email"); CREATE UNIQUE INDEX "Lead_normalizedPhone_key" ON "Lead"("normalizedPhone"); CREATE INDEX "Lead_normalizedPhone_idx" ON "Lead"("normalizedPhone"); CREATE INDEX "Lead_city_niche_idx" ON "Lead"("city","niche"); CREATE INDEX "LeadHistory_leadId_createdAt_idx" ON "LeadHistory"("leadId","createdAt"); CREATE UNIQUE INDEX "Message_providerMessageId_key" ON "Message"("providerMessageId"); CREATE UNIQUE INDEX "Message_idempotencyKey_key" ON "Message"("idempotencyKey"); CREATE INDEX "Message_conversationId_createdAt_idx" ON "Message"("conversationId","createdAt"); CREATE UNIQUE INDEX "CampaignRecipient_campaignId_leadId_key" ON "CampaignRecipient"("campaignId","leadId"); CREATE UNIQUE INDEX "Template_name_key" ON "Template"("name"); CREATE UNIQUE INDEX "Consent_leadId_key" ON "Consent"("leadId"); CREATE UNIQUE INDEX "OptOut_leadId_key" ON "OptOut"("leadId"); CREATE UNIQUE INDEX "WebhookEvent_eventId_key" ON "WebhookEvent"("eventId"); CREATE INDEX "AuditLog_timestamp_idx" ON "AuditLog"("timestamp");
ALTER TABLE "Lead" ADD CONSTRAINT "Lead_assignedUserId_fkey" FOREIGN KEY ("assignedUserId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "LeadNote" ADD CONSTRAINT "LeadNote_leadId_fkey" FOREIGN KEY ("leadId") REFERENCES "Lead"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "LeadNote" ADD CONSTRAINT "LeadNote_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "LeadHistory" ADD CONSTRAINT "LeadHistory_leadId_fkey" FOREIGN KEY ("leadId") REFERENCES "Lead"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Conversation" ADD CONSTRAINT "Conversation_leadId_fkey" FOREIGN KEY ("leadId") REFERENCES "Lead"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Message" ADD CONSTRAINT "Message_conversationId_fkey" FOREIGN KEY ("conversationId") REFERENCES "Conversation"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "CampaignRecipient" ADD CONSTRAINT "CampaignRecipient_campaignId_fkey" FOREIGN KEY ("campaignId") REFERENCES "Campaign"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "CampaignRecipient" ADD CONSTRAINT "CampaignRecipient_leadId_fkey" FOREIGN KEY ("leadId") REFERENCES "Lead"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Consent" ADD CONSTRAINT "Consent_leadId_fkey" FOREIGN KEY ("leadId") REFERENCES "Lead"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "OptOut" ADD CONSTRAINT "OptOut_leadId_fkey" FOREIGN KEY ("leadId") REFERENCES "Lead"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Task" ADD CONSTRAINT "Task_leadId_fkey" FOREIGN KEY ("leadId") REFERENCES "Lead"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Task" ADD CONSTRAINT "Task_assignedTo_fkey" FOREIGN KEY ("assignedTo") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "AuditLog" ADD CONSTRAINT "AuditLog_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
